import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"1959年 核心总结","description":"","frontmatter":{},"headers":[],"relativePath":"01_letters/1959年/核心总结.md","filePath":"01_letters/1959年/核心总结.md"}'),l={name:"01_letters/1959年/核心总结.md"};function i(n,a,s,_,h,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="_1959年-核心总结" tabindex="-1">1959年 核心总结 <a class="header-anchor" href="#_1959年-核心总结" aria-label="Permalink to &quot;1959年 核心总结&quot;">​</a></h1><h2 id="年度业绩" tabindex="-1">年度业绩 <a class="header-anchor" href="#年度业绩" aria-label="Permalink to &quot;年度业绩&quot;">​</a></h2><p>1959年，巴菲特合伙企业继续超越市场。道琼斯工业平均指数全年上涨16.4%，而合伙企业的盈利达到约25.9%，再次跑赢基准约9.5个百分点。这一成绩在连续两年大幅跑赢之后，进一步巩固了巴菲特在合伙人群体中的信誉与声望。值得注意的是，合伙企业的资产规模在1959年已达到相当可观的水平，资金量的增长也对投资策略的灵活性提出了新的挑战。巴菲特开始更多地将资金配置到控制类投资中，而非单纯依赖公开市场的价格波动。</p><h2 id="重要事件" tabindex="-1">重要事件 <a class="header-anchor" href="#重要事件" aria-label="Permalink to &quot;重要事件&quot;">​</a></h2><p>蓝筹印花公司（Blue Chip Stamp）在1959年成为合伙企业持仓中占比显著加大的资产。巴菲特逐步意识到，这家看似不起眼的印花兑换公司，实际上拥有极为独特的现金流特征：它预先收取客户资金，却延迟兑换——这意味着公司账上长期维持着大量&quot;浮存金&quot;。这些资金可以被持续地投资于其他有价值的资产，形成一个隐形的投资平台。巴菲特与好友汤姆·纳特等人共同扩大了对蓝筹印花的控制权，并逐步将其整合进更宏大的资本运作版图。</p><h2 id="投资理念" tabindex="-1">投资理念 <a class="header-anchor" href="#投资理念" aria-label="Permalink to &quot;投资理念&quot;">​</a></h2><p>1959年，巴菲特在信中发出了对市场投机情绪的明确警告。股市连续多年的上涨已经让市场整体估值攀升至历史高位，大量投资者开始忽视基本面，追逐热门股票，整个市场的投机氛围日趋浓厚。巴菲特坦言，在这样的市场环境中维持超额收益愈发困难，&quot;好价格&quot;的好公司变得越来越稀缺。他提醒合伙人，真正的风险不是市场下跌，而是为成长支付过高的溢价。这一警告在日后多次得到验证，成为他应对市场狂热时的一贯态度。</p><h2 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h2><p>蓝筹印花的投资版图中，沃伦·巴菲特与汤姆·纳特（Tom Knapp）共同行动，后者是巴菲特的早期合伙人兼老友，也是专业投资人，两人共同推进了对蓝筹印花的控股进程。与此同时，巴菲特与查理·芒格（Charlie Munger）的关系在这一时期明显深化，芒格的法律背景和跨学科思维为巴菲特提供了宝贵的视角补充。本杰明·格雷厄姆虽已退休，但他的投资哲学仍深刻影响巴菲特的每一次决策。</p>',9)])])}const u=e(l,[["render",i]]);export{p as __pageData,u as default};
